        {"level": "running_header", "text": "HEIDEGGER EN FRANCE", "position": "top"}
      ],
      "paragraph_starts": [
        {"text": "sophe a accepté de jouer à plus d'une reprise (de l'engagement", "continues_from_previous": false, "continues_to_next": false},
        {"text": "Heidegger avoue avoir beaucoup hésité avant de se décider à ce voyage", "continues_from_previous": false, "continues_to_next": false},
        {"text": "La foule des censeurs de Heidegger ne manquera pas d'en tirer argument", "continues_from_previous": false, "continues_to_next": false}
      ],
      "body_note_refs": [
        {"marker": "65", "context": "confortable croisière"},
        {"marker": "66", "context": "vie du peuple grec d'aujourd'hui (à se méfier de Mycènes"},
        {"marker": "67", "context": "frivolité minoennes en Crète"},
        {"marker": "68", "context": "travaux de Walter F. Otto"}
      ],
      "footnotes": [
        {"marker": "65", "text_start": "Voir, sur ce point, Entretiens (AXELOS)."},
        {"marker": "66", "text_start": "Heidegger, Séjours..., trad. citée, pp. 32-33."},
        {"marker": "67", "text_start": "Ibid., pp. 38-41."},
        {"marker": "68", "text_start": "De ce grand helléniste, très admiré de Heidegger, les principales publications qu'on peut lire en français sont:"}
      ],
      "risks": []
