    {
      "label": "ch11 PDF page 19",
      "printed_page": "409",
      "headings": [
        {"level": "running_header", "text": "ENTRE ÉRUDITION ET TECHNO-SCIENCE", "position": "top"}
      ],
      "paragraph_starts": [
        {"text": "« aux prises avec le secret de l'Aletheïa 69 » et, à Égine,", "continues_from_previous": false, "continues_to_next": false},
        {"text": "Est-il trop facile d'objecter que Heidegger transporte avec lui sa Grèce,", "continues_from_previous": false, "continues_to_next": false},
        {"text": "Voyage savant donc, puisque le lieu ne livre sa « vérité » qu'à la lumière", "continues_from_previous": false, "continues_to_next": false}
      ],
      "body_note_refs": [
        {"marker": "69", "context": "secret de l'Aletheïa"},
        {"marker": "70", "context": "ce qui se déclôt"},
