        {"marker": "70", "text_start": "Ibid., pp. 72-73."},
        {"marker": "71", "text_start": "Ibid., pp. 24-25."},
        {"marker": "72", "text_start": "C'est d'ailleurs un grand mérite de Heidegger que de l'avoir reconnu, dans les termes explicites d'une autocritique"}
      ],
