    {
      "label": "ch11 PDF page 20",
      "printed_page": "410",
      "headings": [
        {"level": "running_header", "text": "HEIDEGGER EN FRANCE", "position": "top"}
      ],
      "paragraph_starts": [
        {"text": "était originellement séjour. Voyage beaucoup plus étrange que ne le laissent", "continues_from_previous": true, "continues_to_next": false},
        {"text": "Oubliez-vous, objectera-t-on, l'autre pôle, la techno-science ? Nullement.", "continues_from_previous": false, "continues_to_next": false},
